<script>
import {onMount} from 'svelte';
import {get} from 'svelte/store';
import {data,profile,updateData,notify,download,setTerm} from '../lib/store.js';
import {TERMS,COURSES,sectionById,courseLabel} from '../lib/catalog.js';
import {addToCart,enrollSections,validateBatch,eligibility,creditSum,meetingLabel,searchSections,waitlistSection,dropSection,scheduleICS,plannedCampusDays} from '../lib/model.js';
import Icon from '../lib/components/Icon.svelte';import Modal from '../lib/components/Modal.svelte';import Schedule from '../lib/components/Schedule.svelte';
let {params=new URLSearchParams()}=$props();
let tab=$state('find');let filtersOpen=$state(false);let details=$state(null);let compared=$state([]);let showCompare=$state(false);let reviewIds=$state(null);let receipt=$state(null);let dropping=$state(null);
onMount(()=>{if(TERMS.some(t=>t.id===params.get('term')))setTerm(params.get('term'));if(params.get('tab')==='schedule')tab='schedule';if(params.get('q')){if($data.termId!=='spring-2027')setTerm('spring-2027');filter({query:params.get('q')});}});
let term=$derived(TERMS.find(t=>t.id===$data.termId));let termId=$derived(term.id);let enrolled=$derived($data.enrolledByTerm[termId]??[]);let cartIds=$derived($data.cartByTerm[termId]??[]);let cart=$derived(cartIds.map(sectionById).filter(Boolean));let waitlist=$derived(($data.waitlistByTerm[termId]??[]).map(sectionById).filter(Boolean));
let context=$derived({query:'',subject:'All subjects',openOnly:false,mode:'All formats',day:'',hideConflicts:false,startAfter:'',endBefore:'',fitCampusDays:false,...($data.searchByTerm[termId]??{})});
let filtered=$derived(searchSections(context,$data,termId));let grouped=$derived(COURSES.map(c=>({...c,matches:filtered.filter(s=>s.code===c.code)})).filter(c=>c.matches.length));
let campusDays=$derived(plannedCampusDays($data,termId));
let invalidTimeRange=$derived(!!context.startAfter&&!!context.endBefore&&context.startAfter>=context.endBefore);
let problems=$derived(reviewIds?validateBatch($data,$profile,reviewIds,termId):[]);let reviewSections=$derived((reviewIds??[]).map(sectionById).filter(Boolean));
function filter(patch){updateData({...$data,searchByTerm:{...$data.searchByTerm,[termId]:{...context,...patch}}});}
function clearFilters(){updateData({...$data,searchByTerm:{...$data.searchByTerm,[termId]:{}}});}
function add(id){const result=addToCart($data,id,termId);if(result.ok){updateData(result.state);notify('Added to your cart. Your seat is not reserved.',{action:()=>tab='cart',actionLabel:'View cart'});}else notify(result.message,{kind:'error'});}
function remove(id){updateData({...$data,cartByTerm:{...$data.cartByTerm,[termId]:cartIds.filter(x=>x!==id)}});notify('Removed from your cart.');}
function enroll(){const result=enrollSections($data,$profile,reviewIds,termId);if(result.ok){updateData(result.state);reviewIds=null;details=null;receipt=result.receipt;tab='schedule';}else notify('Resolve the highlighted issues before enrolling.',{kind:'error'});}
function join(id){const result=waitlistSection($data,$profile,id,termId);if(result.ok){updateData(result.state);notify('You joined the demo waitlist. You are not enrolled.');}else notify(result.message,{kind:'error'});}
function drop(){const result=dropSection($data,dropping.id,termId);if(result.ok){updateData(result.state);dropping=null;const restoreTerm=termId;notify(`${result.section.code} was removed from your schedule.`,{actionLabel:'Undo',action:()=>{const live=get(data);const current=live.enrolledByTerm[restoreTerm]??[];if(!current.some(s=>s.code===result.section.code)){updateData({...live,enrolledByTerm:{...live.enrolledByTerm,[restoreTerm]:[...current,result.section]}});notify('Class restored to your schedule.');}}});}}
function compare(id){compared=compared.includes(id)?compared.filter(x=>x!==id):compared.length<3?[...compared,id]:compared;if(compared.length===3)notify('Compare up to three sections at a time.');}
function switchTerm(id){setTerm(id);compared=[];details=null;reviewIds=null;}
function exportSchedule(){download(`catalyst-${termId}.ics`,scheduleICS(enrolled,termId),'text/calendar');notify('Calendar downloaded. Demo meeting dates are illustrative.');}
</script>
<div class="page-heading"><div><p class="eyebrow">Make your next move</p><h1>Classes & schedule</h1><p>Find the right fit. Know where you stand. Keep moving forward.</p></div><label class="term-control"><span class="sr-only">Registration term</span><select value={termId} onchange={e=>switchTerm(e.currentTarget.value)}>{#each TERMS as t}<option value={t.id}>{t.label}{t.current?' · Current':''}</option>{/each}</select></label></div>
<div class:open={term.registrationOpen} class="registration-banner"><span class="round-icon"><Icon name={term.registrationOpen?'check':'info'}/></span><div><strong>{term.registrationOpen?'Your enrollment window is open.':'Your current semester, all in one place.'}</strong><p>{term.registrationOpen?'Spring 2027 · Up to 18 credits · Demo registration':term.reason}</p></div><a href="#/services?category=Planning" class="text-link">Dates & deadlines<Icon name="arrow" size={16}/></a></div>
<div class="section-tabs" aria-label="Class workspace"><button class:active={tab==='find'} aria-pressed={tab==='find'} onclick={()=>tab='find'}><Icon name="search" size={17}/>Find classes</button><button class:active={tab==='schedule'} aria-pressed={tab==='schedule'} onclick={()=>tab='schedule'}><Icon name="calendar" size={17}/>My schedule<span class="count">{enrolled.length}</span></button><button class:active={tab==='cart'} aria-pressed={tab==='cart'} onclick={()=>tab='cart'}><Icon name="cart" size={17}/>Enrollment cart<span class="count">{cart.length}</span></button></div>
{#if tab==='find'}
 {#if !term.registrationOpen}<section class="panel empty-state"><Icon name="calendar" size={32}/><h2>Looking ahead?</h2><p>Class search is available for the next registration term. Your current classes are under My schedule.</p><button class="button primary" onclick={()=>switchTerm('spring-2027')}>Explore Spring 2027<Icon name="arrow" size={16}/></button></section>
 {:else}
 <div class="class-layout"><div class="class-main"><div class="search-box"><Icon name="search"/><input aria-label="Search classes by course code, title, or instructor" type="search" placeholder="Course, keyword, or instructor…" value={context.query} oninput={e=>filter({query:e.currentTarget.value})}/></div><div class="filter-bar"><label><span class="sr-only">Subject</span><select value={context.subject} onchange={e=>filter({subject:e.currentTarget.value})}><option>All subjects</option>{#each [...new Set(COURSES.map(c=>c.subject))] as subject}<option>{subject}</option>{/each}</select></label><label class="checkbox-label"><input type="checkbox" checked={context.openOnly} onchange={e=>filter({openOnly:e.currentTarget.checked})}/>Open seats only</label><button class="button quiet" aria-expanded={filtersOpen} onclick={()=>filtersOpen=!filtersOpen}><Icon name="filter" size={16}/>Filters</button></div>
 {#if filtersOpen}<div class="filter-panel panel"><label>Format<select value={context.mode} onchange={e=>filter({mode:e.currentTarget.value})}><option>All formats</option><option>In person</option><option>Online</option></select></label><label>Meeting day<select value={context.day} onchange={e=>filter({day:e.currentTarget.value})}><option value="">Any day</option>{#each ['Mon','Tue','Wed','Thu','Fri'] as day}<option>{day}</option>{/each}</select></label><label class="checkbox-label"><input type="checkbox" checked={context.hideConflicts} onchange={e=>filter({hideConflicts:e.currentTarget.checked})}/>Hide conflicts with enrolled classes</label><label>Starts at or after<input type="time" value={context.startAfter} oninput={e=>filter({startAfter:e.currentTarget.value})}/></label><label>Ends at or before<input type="time" value={context.endBefore} oninput={e=>filter({endBefore:e.currentTarget.value})}/></label><label class="checkbox-label"><input type="checkbox" checked={context.fitCampusDays} onchange={e=>filter({fitCampusDays:e.currentTarget.checked})}/>Keep to my campus days</label><p class="filter-explanation">{campusDays.length?`Your enrolled classes and cart use ${campusDays.join(', ')}. The campus-day filter keeps new meetings on those days.`:'Add a scheduled class to your cart to establish your campus days.'} Time filters require every meeting to fit; asynchronous sections are hidden while a time filter is active.</p>{#if invalidTimeRange}<p class="warning-text full-span" role="alert">Choose an end time later than the start time, or clear one of the time filters.</p>{/if}<button class="text-link" onclick={clearFilters}>Reset filters</button></div>{/if}
 <div class="results-meta" role="status"><span><strong>{grouped.length}</strong> {grouped.length===1?'course':'courses'} · {filtered.length} {filtered.length===1?'section':'sections'}</span><span>Synthetic course catalog</span></div>
 {#if !grouped.length}<div class="empty-state panel"><Icon name="search" size={30}/><h2>No classes match yet.</h2><p>Try a broader keyword, another day, or include full sections.</p><button class="button secondary" onclick={clearFilters}>Clear all filters</button></div>{/if}
 {#each grouped as course}<article class="course-card panel"><div class="course-card-head"><div><span class="eyebrow">{course.code} <span class="muted">/ {course.category}</span></span><button class="course-title" onclick={()=>details=course.code}>{course.title}</button><p class="muted small">{course.credits} credits · {course.prerequisites.length?`Prerequisite: ${course.prerequisites.map(courseLabel).join(', ')}`:'No prerequisites'}</p></div><button class="icon-button" aria-label={`View details for ${course.title}`} onclick={()=>details=course.code}><Icon name="arrow"/></button></div>
  {#each course.matches as s}{@const issues=eligibility($data,$profile,s,termId)}{@const inCart=cartIds.includes(s.id)}{@const isEnrolled=enrolled.some(c=>c.id===s.id)}<div class="section-row"><div><strong class="section-code">Section {s.section}</strong><p class="small muted">{s.instructor}</p><label class="compare-check"><input type="checkbox" checked={compared.includes(s.id)} onchange={()=>compare(s.id)}/>Compare</label></div><div class="section-meeting"><p><Icon name="clock" size={14}/>{meetingLabel(s)}</p><p class="small muted"><Icon name="location" size={14}/>{s.meetings.map(m=>m.room).join(', ')||'Online · no set meeting time'}</p>{#if issues.some(e=>e.code==='conflict')}<span class="badge warning">Schedule conflict</span>{/if}{#if issues.some(e=>e.code==='prerequisite')}<span class="badge warning">Prerequisite needed</span>{/if}</div><div class="section-seat"><span class:success={s.seats>0} class:warning={s.seats===0} class="badge">{s.seats>0?`${s.seats} open seats`:'Full · waitlist'}</span>{#if isEnrolled}<span class="badge success"><Icon name="check" size={13}/>Enrolled</span>{:else if inCart}<button class="button secondary small-button" onclick={()=>tab='cart'}><Icon name="check" size={14}/>In cart</button>{:else if s.seats===0}<button class="button secondary small-button" disabled={waitlist.some(w=>w.id===s.id)} onclick={()=>join(s.id)}>{waitlist.some(w=>w.id===s.id)?'Waitlisted':'Join waitlist'}</button><small class="waitlist-limits">No queue position or notifications in this demo.</small>{:else}<button class="button secondary small-button" onclick={()=>add(s.id)}><Icon name="plus" size={14}/>Add to cart</button>{/if}</div></div>{/each}
 </article>{/each}</div>
 <aside class="planning-rail"><section class="panel padded"><div class="section-heading"><h3>Your spring plan</h3><Icon name="calendar" size={19}/></div><div class="plan-total"><strong>{creditSum(enrolled)}</strong><span>/ 18 credits enrolled</span></div><div class="progress-track"><span style:width={`${Math.min(100,creditSum(enrolled)/18*100)}%`}></span></div><p class="muted small">{enrolled.length?`${enrolled.length} classes confirmed for Spring 2027.`:'Your schedule starts with one good choice.'}</p>{#each enrolled as c}<div class="mini-course"><span class="status-dot"></span><div><strong>{c.code}</strong><p>{c.title}</p></div></div>{/each}<button class="button secondary full" onclick={()=>tab='schedule'}>View my schedule<Icon name="arrow" size={15}/></button></section><section class="cart-summary"><Icon name="cart" size={25}/><h3>{cart.length?`${cart.length} ${cart.length===1?'class':'classes'} in your cart`:'A cart is a plan, not a seat.'}</h3><p>Classes in your cart are not reserved. Review your selections and complete enrollment to confirm your schedule.</p>{#if cart.length}<button class="button primary full" onclick={()=>tab='cart'}>Review cart<Icon name="arrow" size={15}/></button>{/if}</section><a class="advisor-link" href="#/services?category=Advising"><Icon name="people" size={20}/><span>Need a second opinion?<strong>Find academic advising</strong></span><Icon name="arrow" size={16}/></a></aside></div>
 {/if}
{:else if tab==='cart'}
 <div class="section-heading"><div><h2>Your enrollment cart</h2><p class="muted">{term.label} · Seats are not reserved until enrollment is confirmed.</p></div>{#if cart.length}<button class="button primary" onclick={()=>reviewIds=[...cartIds]}>Review & enroll<Icon name="arrow" size={16}/></button>{/if}</div>
 {#if !cart.length}<section class="panel empty-state"><span class="empty-icon"><Icon name="cart" size={30}/></span><h2>Good plans start here.</h2><p>Your cart is empty for {term.label}. Add sections from class search, then review them together.</p><button class="button primary" onclick={()=>tab='find'}>Find classes<Icon name="arrow" size={16}/></button></section>{/if}
 {#each cart as s}{@const issues=eligibility($data,$profile,s,termId,cart.filter(x=>x.id!==s.id))}<article class="panel cart-course"><div class="section-heading"><div><span class="eyebrow">{s.code} · Section {s.section}</span><h3>{s.title}</h3><p class="muted small">{meetingLabel(s)} · {s.credits} credits</p></div><button class="button quiet" onclick={()=>remove(s.id)}><Icon name="close" size={16}/>Remove</button></div>{#if issues.length}<div class="inline-issues">{#each issues as issue}<p><Icon name="warning" size={16}/><span><strong>{issue.message}</strong> {issue.recovery}</span></p>{/each}<button class="text-link" onclick={()=>{tab='find';filter({query:s.code});}}>Find another section<Icon name="arrow" size={14}/></button></div>{:else}<p class="eligibility-ok"><Icon name="check" size={16}/>Ready for review · prerequisite and schedule checks passed</p>{/if}</article>{/each}
 {:else}
 <div class="section-heading"><div><h2>Your confirmed classes</h2><p class="muted">{term.label} · {enrolled.length} {enrolled.length===1?'class':'classes'} · {creditSum(enrolled)} credits</p></div><div class="button-row"><button class="button secondary" disabled={!enrolled.length} onclick={exportSchedule}><Icon name="download" size={16}/>Export calendar</button><button class="button secondary" onclick={()=>window.print()}><Icon name="file" size={16}/>Print</button></div></div>
 <section class="panel padded"><Schedule courses={enrolled} {termId} compact={$data.preferences.compactSchedule}/></section>
 {#if enrolled.length}<div class="enrolled-list">{#each enrolled as s}<div class="panel enrolled-item"><div><strong>{s.code} · {s.title}</strong><p class="muted small">Section {s.section} · {meetingLabel(s)}</p></div><span class="badge success"><Icon name="check" size={14}/>Enrolled</span>{#if term.registrationOpen}<button class="button quiet danger" onclick={()=>dropping=s}>Drop class</button>{/if}</div>{/each}</div>{/if}
 {#if waitlist.length}<section class="panel padded waitlist"><h3>Waitlisted · not enrolled</h3><p class="muted small">A waitlist does not guarantee a place. Position is unavailable in this demo. It does not send notifications or automatically enroll you.</p>{#each waitlist as s}<div class="enrolled-item"><div><strong>{s.code} · Section {s.section}</strong><p class="muted small">{s.title}</p></div><span class="badge warning">Waiting</span><button class="button quiet" onclick={()=>{updateData({...$data,waitlistByTerm:{...$data.waitlistByTerm,[termId]:waitlist.filter(x=>x.id!==s.id).map(x=>x.id)}});notify('Removed from the waitlist.');}}>Leave waitlist</button></div>{/each}</section>{/if}
 {#if $data.receipts.filter(r=>r.termId===termId).length}<section class="panel padded"><h3>Enrollment confirmations</h3>{#each $data.receipts.filter(r=>r.termId===termId) as r}<button class="receipt-link" onclick={()=>receipt=r}><Icon name="file" size={18}/><span><strong>{r.id}</strong><small>{r.courses.map(c=>c.code).join(', ')} · {new Date(r.timestamp).toLocaleDateString()}</small></span><Icon name="arrow" size={16}/></button>{/each}</section>{/if}
{/if}
{#if compared.length && tab==='find'}<div class="compare-tray"><span><strong>{compared.length}</strong> section{compared.length===1?'':'s'} selected</span><button class="text-link" onclick={()=>compared=[]}>Clear</button><button class="button primary" disabled={compared.length<2} onclick={()=>showCompare=true}>Compare sections<Icon name="arrow" size={15}/></button></div>{/if}
{#if details}{@const c=COURSES.find(c=>c.code===details)}<Modal title={c.title} onclose={()=>details=null} wide><span class="eyebrow">{c.code} · {c.credits} credits · {c.category}</span><p class="modal-intro">{c.description}</p><div class="notice"><Icon name="info"/><p><strong>Prerequisites</strong><br/>{c.prerequisites.map(courseLabel).join(', ')||'None'}. In-progress fall prerequisites may support spring planning, contingent on successful completion.</p></div><h3 class="spaced">Compare available sections</h3>{#each c.sections as raw}{@const s=sectionById(raw.id)}<div class="detail-section"><div><strong>Section {s.section} · {s.instructor}</strong><p class="muted small">{meetingLabel(s)}</p><p class="small">{s.seats>0?`${s.seats} seats available`:'Full · waitlist available'}</p></div><button class="button secondary" onclick={()=>{if(s.seats){add(s.id);}else join(s.id);details=null;}}>{s.seats?'Add to cart':'Join waitlist'}<Icon name="plus" size={14}/></button></div>{/each}<p class="fine-print">All section offerings and seat counts are synthetic demo data.</p></Modal>{/if}
{#if showCompare}<Modal title="Compare your options" onclose={()=>showCompare=false} wide><div class="comparison-grid">{#each compared.map(sectionById) as s}<div class="panel padded"><span class="eyebrow">{s.code} · {s.section}</span><h3>{s.title}</h3><dl class="comparison-details"><div><dt>Meets</dt><dd>{meetingLabel(s)}</dd></div><div><dt>Instructor</dt><dd>{s.instructor}</dd></div><div><dt>Credits</dt><dd>{s.credits}</dd></div><div><dt>Seats</dt><dd>{s.seats||'Full'}</dd></div><div><dt>Prerequisites</dt><dd>{s.prerequisites.map(courseLabel).join(', ')||'None'}</dd></div></dl>{#each eligibility($data,$profile,s,termId) as issue}<p class="small warning-text">{issue.message}</p>{/each}<button class="button secondary full" onclick={()=>{s.seats?add(s.id):join(s.id);}}>{s.seats?'Add to cart':'Join waitlist'}</button></div>{/each}</div></Modal>{/if}
{#if reviewIds}<Modal title="Review before you enroll" onclose={()=>reviewIds=null} wide><p class="modal-intro">{term.label} · {reviewSections.length} classes · {creditSum(reviewSections)} credits</p><div class="notice"><Icon name="shield"/><p>Your classes are still in planning. Enrollment is complete only after you receive a confirmation.</p></div>{#each reviewSections as s}{@const issue=problems.find(p=>p.id===s.id)}<div class="review-row"><div><strong>{s.code} · {s.title}</strong><p class="muted small">Section {s.section} · {meetingLabel(s)}</p></div><span class="badge" class:warning={!!issue} class:success={!issue}>{issue?'Needs attention':'Ready'}</span>{#if issue}<div class="inline-issues full-span">{#each issue.errors as e}<p><Icon name="warning" size={16}/><span><strong>{e.message}</strong><br/>{e.recovery}</span></p>{/each}</div>{/if}</div>{/each}{#if problems.length}<p class="warning-text spaced">Resolve these issues in your cart before continuing. No classes have been enrolled.</p>{:else}<p class="eligibility-ok spaced"><Icon name="check" size={18}/>Schedule, prerequisites, seat availability, and credit limit checked.</p>{/if}<div class="modal-actions"><button class="button secondary" onclick={()=>{reviewIds=null;tab='cart';}}>Back to cart</button><button class="button primary" disabled={problems.length>0} onclick={enroll}>Confirm enrollment<Icon name="check" size={16}/></button></div><p class="fine-print">Prototype only. This does not register you for actual UC courses.</p></Modal>{/if}
{#if receipt}<Modal title="You’re enrolled. You’re all set." onclose={()=>receipt=null}><div class="success-seal"><Icon name="check" size={32}/></div><p class="center muted">Your demo registration for {TERMS.find(t=>t.id===receipt.termId)?.label} is confirmed.</p><div class="confirmation-box"><span class="eyebrow">Confirmation number</span><strong>{receipt.id}</strong><small>{new Date(receipt.timestamp).toLocaleString()}</small></div>{#each receipt.courses as c}<div class="detail-section"><div><strong>{c.code} · {c.title}</strong><p class="muted small">Section {c.section} · {c.credits} credits</p></div><Icon name="check" size={18}/></div>{/each}<p class="fine-print">This records the enrollment at that time. Your current schedule reflects any later drops.</p><div class="modal-actions"><button class="button secondary" onclick={()=>download(`${receipt.id}.json`,JSON.stringify(receipt,null,2),'application/json')}>Save receipt</button><button class="button primary" onclick={()=>{receipt=null;tab='schedule';}}>View schedule<Icon name="arrow" size={16}/></button></div></Modal>{/if}
{#if dropping}<Modal title="Drop this class?" onclose={()=>dropping=null}><p class="modal-intro"><strong>{dropping.code} · {dropping.title}</strong><br/>Section {dropping.section} · {dropping.credits} credits · {term.label}</p><div class="notice warning-notice"><Icon name="warning"/><p>This removes the class from your demo schedule. Your total will change to {creditSum(enrolled)-dropping.credits} credits. You can undo immediately afterward.</p></div><p class="fine-print">For real enrollment, check official deadlines and financial-aid implications with UC.</p><div class="modal-actions"><button class="button secondary" onclick={()=>dropping=null}>Keep class</button><button class="button danger-button" onclick={drop}>Drop class</button></div></Modal>{/if}
